-- REM-A7-DOI-SWEEP-2 (2026-10-26, remediation agent rem-a7 fork F4; charter pillars reach and security; agent_issues 100587; follow-up of migrations/2026-10-26-rem-a7-doi-sweep.sql, applied 18:51Z).
-- The first file rewrote one registry sentence on each of the two cms pages (content_entries 9 qnfo-publications and 11 living-papers) because the inspection that found them read only the first occurrence. The contract probe of issue 100587
-- then read 2 instead of 0 (remediation probe run live at 18:55Z), and the evidence guard of the first file correctly did not stage the close evidence. Three mentions remain, all on those pages: "- A Zenodo DOI when formally published" (page 9, a list item),
-- "- **6 with Zenodo DOIs** (published papers)" (page 11, a statistics line) and "4. **Published**: Zenodo DOI assigned, formally published" (page 11, a lifecycle stage). Each is reworded exactly (a guarded replace of that text only); the pages' other text is unchanged.
-- The close of issue 100587 should rest on the sweep and not on three tables, so four contracts are added to the issue (the auto-close trigger waits for every active contract of an issue; the first contract, the count of the cleared fields, is unchanged):
--   * noz-sweep-100587-no-reentry (d1-query, daily): no ledger or stats table of qnfo-audit holds more closed-registry identifiers than the 2026-10-26 baseline (18 columns, read the same day) and the cleared tables hold none; a re-entry names the table;
--   * noz-sweep-100587-surface-api (runner-https, daily): papers.qnfo.org/api/papers?limit=100 answers 200 and carries no 10.5281 (423,697 bytes, under the runner's 512 KiB read);
--   * noz-sweep-100587-surface-llms (runner-https, daily): qnfo.org/llms.txt answers 200 and carries no registry name;
--   * noz-sweep-100587-inventory (code-read, daily): docs/DOI-ZENODO-INVENTORY.md and scripts/doi-zenodo-inventory.mjs are on main.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE content_entries SET body_md = (SELECT b.body_md FROM bak_noz2b_content_entries_20261026 b WHERE b.id = content_entries.id) WHERE id IN (SELECT id FROM bak_noz2b_content_entries_20261026); UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:rollback REM-A7-DOI-SWEEP-2' WHERE class IN ('noz-sweep-100587-no-reentry', 'noz-sweep-100587-surface-api', 'noz-sweep-100587-surface-llms', 'noz-sweep-100587-inventory'); UPDATE issue_triage SET close_evidence = NULL WHERE issue_id = 100587 AND close_evidence LIKE 'SWEEP DONE%'

CREATE TABLE IF NOT EXISTS bak_noz2b_content_entries_20261026 AS SELECT id, slug, body_md FROM content_entries WHERE id IN (9, 11) AND instr(lower(coalesce(body_md, '')), 'zenodo') > 0;
UPDATE content_entries SET body_md = replace(body_md, '- A Zenodo DOI when formally published', '- A stable address at papers.qnfo.org') WHERE id = 9 AND instr(body_md, '- A Zenodo DOI when formally published') > 0;
UPDATE content_entries SET body_md = replace(body_md, '- **6 with Zenodo DOIs** (published papers)' || char(10), '') WHERE id = 11 AND instr(body_md, '- **6 with Zenodo DOIs** (published papers)') > 0;
UPDATE content_entries SET body_md = replace(body_md, '4. **Published**: Zenodo DOI assigned, formally published', '4. **Published**: Formally published at papers.qnfo.org') WHERE id = 11 AND instr(body_md, '4. **Published**: Zenodo DOI assigned') > 0;

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
SELECT 'noz-sweep-100587-no-reentry', 100587, 'REM-A7-DOI-SWEEP-1 and -2 are applied (display tables cleared, ledgers measured 2026-10-26)', 'a closed-registry identifier re-entered a table of qnfo-audit: find the writer and filter it (NOZ-DOI-1)', 'WITH x AS (SELECT trim(CASE WHEN (SELECT COUNT(*) FROM zenodo_stats WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 575 THEN ''zenodo_stats '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM zenodo_exit_ledger WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 914 THEN ''zenodo_exit_ledger '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM zenodo_attribution_audit WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 573 THEN ''zenodo_attribution_audit '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM zenodo_version_requests WHERE instr(coalesce(result_doi, ''''), ''10.5281'') > 0) > 1 THEN ''zenodo_version_requests '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM jnl_records WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 1 THEN ''jnl_records '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM jnlaudit_records WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 22 THEN ''jnlaudit_records '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM citation_stats WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 5207 THEN ''citation_stats '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM impact_scores WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 122 THEN ''impact_scores '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM entity_map WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 1 THEN ''entity_map '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM social_threads WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 62 THEN ''social_threads '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM social_media_posts WHERE instr(coalesce(paper_doi, ''''), ''10.5281'') > 0) > 4 THEN ''social_media_posts '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM dissemination_tracker WHERE instr(coalesce(paper_doi, ''''), ''10.5281'') > 0) > 62 THEN ''dissemination_tracker '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM research_queue WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 47 THEN ''research_queue '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM errata_queue WHERE instr(coalesce(paper_doi, ''''), ''10.5281'') > 0) > 3 THEN ''errata_queue '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM errata_actions WHERE instr(coalesce(paper_doi, ''''), ''10.5281'') > 0) > 2 THEN ''errata_actions '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM version_queue WHERE instr(coalesce(paper_doi, ''''), ''10.5281'') > 0) > 60 THEN ''version_queue '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM paper_revision_log WHERE instr(coalesce(doi, ''''), ''10.5281'') > 0) > 459 THEN ''paper_revision_log '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM proofs WHERE instr(coalesce(paper_doi, ''''), ''10.5281'') > 0) > 12 THEN ''proofs '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM dissemination_tracker WHERE coalesce(zenodo_url, '''') <> '''') > 56 THEN ''dissemination_tracker.zenodo_url '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM research_code_libraries WHERE instr(coalesce(companion_doi, ''''), ''10.5281'') > 0) > 0 THEN ''research_code_libraries '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM paper_index WHERE coalesce(doi, '''') <> '''' OR coalesce(zenodo_id, '''') <> '''' OR coalesce(zenodo_url, '''') <> '''' OR coalesce(related_zenodo_ids, '''') <> '''') > 0 THEN ''paper_index '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM content_entries WHERE coalesce(doi, '''') <> '''' OR coalesce(zenodo_id, '''') <> '''' OR instr(lower(coalesce(body_md, '''')), ''zenodo'') > 0 OR instr(lower(coalesce(body_html, '''')), ''zenodo'') > 0 OR instr(lower(coalesce(abstract, '''')), ''zenodo'') > 0 OR instr(lower(coalesce(bibliography_json, '''')), ''zenodo'') > 0 OR instr(lower(coalesce(meta_json, '''')), ''zenodo'') > 0) > 0 THEN ''content_entries '' ELSE '''' END || CASE WHEN (SELECT COUNT(*) FROM discovery_projects WHERE coalesce(doi, '''') <> '''' OR instr(lower(coalesce(description, '''')), ''zenodo'') > 0 OR instr(lower(coalesce(features, '''')), ''zenodo'') > 0) > 0 THEN ''discovery_projects '' ELSE '''' END) AS over) SELECT ''no table holds more closed-registry identifiers than the 2026-10-26 baseline and the cleared tables hold none'' AS expected, CASE WHEN over = '''' THEN ''no table holds more closed-registry identifiers than the 2026-10-26 baseline and the cleared tables hold none'' ELSE ''over baseline: '' || over END AS observed FROM x', 'd1-query', 3, 'qnfo-fleet-control', 24, 'active', 'rem-a7-doi-sweep-v1', 45000, 5, datetime('now', '-10 minutes')
WHERE EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = 100587 AND a.status = 'open');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
SELECT 'noz-sweep-100587-surface-api', 100587, 'papers.qnfo.org serves its open-data list', 'a closed-registry DOI reached the open-data list: the gateway''s prefix filter lost it (NOZ-DOI-1)', '{"url": "https://papers.qnfo.org/api/papers?limit=100", "status": 200, "absent": "10.5281"}', 'runner-https', 3, 'qnfo-fleet-control', 24, 'active', 'rem-a7-doi-sweep-v1', 45000, 5, datetime('now', '-10 minutes')
WHERE EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = 100587 AND a.status = 'open');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
SELECT 'noz-sweep-100587-surface-llms', 100587, 'qnfo.org serves llms.txt', 'the registry name reached llms.txt: find the generator (NOZ-DOI-1)', '{"url": "https://qnfo.org/llms.txt", "status": 200, "absent": "zenodo"}', 'runner-https', 3, 'qnfo-fleet-control', 24, 'active', 'rem-a7-doi-sweep-v1', 45000, 5, datetime('now', '-10 minutes')
WHERE EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = 100587 AND a.status = 'open');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
SELECT 'noz-sweep-100587-inventory', 100587, 'docs/DOI-ZENODO-INVENTORY.md and the inventory tool were merged', 'the inventory report or its tool was removed from main: restore it (agent_issues 100587)', '{"paths": ["docs/DOI-ZENODO-INVENTORY.md", "scripts/doi-zenodo-inventory.mjs"], "contains": "DOI-ZENODO-INVENTORY-1"}', 'code-read', 3, 'qnfo-fleet-control', 24, 'active', 'rem-a7-doi-sweep-v1', 45000, 5, datetime('now', '-10 minutes')
WHERE EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = 100587 AND a.status = 'open');

UPDATE issue_triage SET close_evidence = 'SWEEP DONE, SAFE REPLACEMENTS APPLIED, REMAINDER FILED (rem-a7 F4, measured 2026-10-26). METHOD: scripts/doi-zenodo-inventory.mjs (new, offline suite) over the tracked files of QNFO/qnfo-workers at 8fb1e92c: 2903 text files scanned, 126 name the registry (829 references: 673 are history records in migrations and handoff documents, 78 owner-authored sources under papers/, 29 guards that filter or refuse the prefix, 25 test fixtures, 7 lines of loop-generated documents, 9 comments, 8 in retired directories and prose), 0 emitter candidates; 63 files carry 337 third-party DOIs, which stay (NOZ-DOI-1 amendment). GitHub code search over the QNFO organisation (130 repositories): 1,416 files name the registry; the first 1,000 read gitbook 530, .github 310, qnfo-workers 62, QWAV 53, revolutionary-quantum-guide 18, agentic-ai-deep-tech-research 10, zenodo-automation 7, ultrametric-game-of-life 6, hardware-pathway 4: owner-authored published-paper sources and a retired deposit tool. LIVE SURFACES: 29 URLs (papers.qnfo.org page, API, JSON feed, RSS, sitemap, llms.txt, OpenAPI, OAI-PMH; qnfo.org; q08.org; qwav.org; fleet.qnfo.org; reading, ideas, mind, me and ask hosts) and 8 paper pages read 0 hits for the registry name and for 10.5281; the only DOIs on them are 32 third-party DOIs in mind.q08.org/api/entries.json (stay); living-paper holds 0 registry identifiers on 704 published rows. CHANGED by migrations 2026-10-26-rem-a7-doi-sweep and -sweep-2 (backups bak_noz2_*_20261026 and bak_noz2b_*): paper_index 161 doi values (120 registry, 40 CHAPTER-FRAGMENT markers, 1 test row), 80 zenodo_id, 1 zenodo_url, 1 related id list set to NULL; content_entries 5 doi values and the two pages qnfo-publications and living-papers reworded without the registry (4 sentences; the first migration left 3 of them, found when the probe read 2 instead of 0, finished by the second); discovery_projects 4 doi values, 2 description parentheses and 1 pending-pipeline phrase; research_code_libraries.companion_doi 3 values cleared (the source of three public repository descriptions). The original contract probe of this issue (the count of those fields) read 173 before and reads 0 now; it is unchanged. Added, so the close rests on the sweep and not on three tables: contracts noz-sweep-100587-no-reentry (no ledger or stats table holds more closed-registry identifiers than the 2026-10-26 baseline, the cleared tables hold none), -surface-api and -surface-llms (papers.qnfo.org/api/papers and qnfo.org/llms.txt stay free of the registry), -inventory (the tool and the report are on main). NOT CHANGED, with the decision recorded in decision_log (nothing is edited, so there is nothing to revert): owner-authored published-paper sources in GitHub repositories and papers/ (no mass edit of published papers; the public pages read 0), the exit ledger and the stats tables keyed by closed DOIs (zenodo_stats 575, zenodo_exit_ledger 927, zenodo_attribution_audit 573, citation_stats 5,221, impact_scores 124, jnl records 23, paper_revision_log 459, version_queue 60, research_queue 47, social_threads 62, dissemination_tracker 62: records and join keys, no collector or emitter reads them since NOZ-DOI-1), the retired proof ledger. FILED with a doer and a closing probe: NOZ-DOI-SWEEP-2A (agent_issues 1000479: three public repository descriptions still carry a closed-registry DOI; fleet-control code task) and NOZ-DOI-SWEEP-2B (1000480: QNFO/.github release-pipeline.yml still calls the disabled registry workflow). Full inventory: docs/DOI-ZENODO-INVENTORY.md.'
 WHERE issue_id = 100587 AND coalesce(close_evidence, '') = ''
   AND (SELECT COUNT(*) FROM paper_index WHERE coalesce(doi, '') <> '' OR coalesce(zenodo_id, '') <> '' OR coalesce(zenodo_url, '') <> '' OR coalesce(related_zenodo_ids, '') <> '') = 0 AND (SELECT COUNT(*) FROM content_entries WHERE coalesce(doi, '') <> '' OR coalesce(zenodo_id, '') <> '' OR instr(lower(coalesce(body_md, '')), 'zenodo') > 0 OR instr(lower(coalesce(body_html, '')), 'zenodo') > 0 OR instr(lower(coalesce(abstract, '')), 'zenodo') > 0 OR instr(lower(coalesce(bibliography_json, '')), 'zenodo') > 0 OR instr(lower(coalesce(meta_json, '')), 'zenodo') > 0) = 0 AND (SELECT COUNT(*) FROM discovery_projects WHERE coalesce(doi, '') <> '' OR instr(lower(coalesce(description, '')), 'zenodo') > 0 OR instr(lower(coalesce(features, '')), 'zenodo') > 0) = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'rem-a7-f4',
  'a close that rests on three display tables is not a sweep: the inventory, the no-re-entry baseline of the ledgers, two live surfaces and the presence of the report are measured too',
  'REM-A7-DOI-SWEEP-2: three remaining registry mentions on two cms pages reworded, four contracts added to issue 100587, close evidence staged once the cleared fields read 0',
  'the contract probe of 100587 read 2 at 18:55Z after the first file (content_entries 9 and 11 still held three mentions); papers.qnfo.org/api/papers?limit=100 is 423,697 bytes with 0 registry hits',
  'applied by migration', 'two rows of content_entries (backup bak_noz2b_content_entries_20261026), four contracts, one staged close_evidence; no worker, paper or secret changed',
  'the Rollback line of migrations/2026-10-26-rem-a7-doi-sweep-2.sql',
  'a re-entry of the closed registry into a ledger or an open-data list is read within a day', 'issue 100587 closes at the first run in which all five contracts pass',
  'reach and security: the sweep stays true after it is done', 'D1 reads of the 18 baseline columns and the cleared tables on 2026-10-26, one GET of the open-data list'
WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.action LIKE 'REM-A7-DOI-SWEEP-2:%%');
